void s256_opt(int iterations, float* a, float* d, float aa[256][256], float bb[256][256])
{
    for (int nl = 0; nl < 10*(iterations/256); nl++) {
        for (int i = 0; i < 256; i++) {
            float a0 = a[0];
            float a1 = (float)1.0 - a0;  // odd indices
            float a2 = a0;               // even indices (>=2)
            for (int j = 1; j < 256; j++) {
                a[j] = (j % 2 == 1) ? a1 : a2;
            }
            for (int j = 1; j < 256; j++) {
                aa[j][i] = a[j] + bb[j][i] * d[j];
            }
        }
    }
}

