                a[j] = (j % 2 == 1) ? a1 : a2;
            }

            // Compute aa[j][i] = a[j] + bb[j][i] * d[j] for j=1..255
            // Unroll by 8
            j = 1;
            for (; j + 7 < 256; j += 8) {
                aa[j+0][i] = a[j+0] + bb[j+0][i] * d[j+0];
                aa[j+1][i] = a[j+1] + bb[j+1][i] * d[j+1];
                aa[j+2][i] = a[j+2] + bb[j+2][i] * d[j+2];
                aa[j+3][i] = a[j+3] + bb[j+3][i] * d[j+3];
